<template><div class="page-container"><PageHeader>角色管理<template #desc>先授权页面，再配置该页面内允许操作的按钮</template></PageHeader>
<div class="filter-bar"><el-button type="primary" @click="open()"><el-icon><Plus/></el-icon>&nbsp;新增角色</el-button><el-alert title="内置角色可以调整权限和名称，但不能删除或修改编码" type="info" :closable="false" show-icon/></div>
<el-table v-loading="loading" :data="rows" border stripe><el-table-column prop="code" label="角色编码" width="150"/><el-table-column prop="name" label="角色名称" width="150"/><el-table-column prop="description" label="说明" min-width="200"/><el-table-column label="已授权页面" width="110" align="center"><template #default="{row}">{{pageCount(row)}}</template></el-table-column><el-table-column label="类型" width="90"><template #default="{row}"><el-tag :type="row.builtin?'primary':'success'">{{row.builtin?'内置':'自定义'}}</el-tag></template></el-table-column><el-table-column label="状态" width="90"><template #default="{row}"><el-tag :type="row.enabled?'success':'info'">{{row.enabled?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="150" fixed="right"><template #default="{row}"><el-button link type="primary" @click="open(row)">配置</el-button><el-button v-if="!row.builtin" link type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table>
<el-dialog v-model="visible" :title="editing?'配置角色':'新增角色'" width="820px" top="4vh"><el-form :model="form" label-width="90px"><el-row :gutter="14"><el-col :span="12"><el-form-item label="角色编码" required><el-input v-model="form.code" :disabled="editing?.builtin" placeholder="例如 MAINTAINER"/></el-form-item></el-col><el-col :span="12"><el-form-item label="角色名称" required><el-input v-model="form.name"/></el-form-item></el-col></el-row><el-form-item label="角色说明"><el-input v-model="form.description"/></el-form-item><el-form-item label="启用状态"><el-switch v-model="form.enabled"/></el-form-item><el-divider content-position="left">页面及按钮权限</el-divider><div class="permission-tip">开启页面后，才可以选择该页面下的操作按钮。未列出按钮的页面表示仅配置访问权限。</div>
<div class="permission-groups"><section v-for="group in catalog" :key="group.pageCode" class="permission-group" :class="{enabled:has(group.pageCode)}"><header><div><b>{{group.pageName}}</b><small>{{group.pageCode}}</small></div><el-switch :model-value="has(group.pageCode)" active-text="允许访问" @change="togglePage(group,$event)"/></header><div v-if="group.actions.length" class="action-area"><span class="action-label">页面内操作</span><el-checkbox v-for="action in group.actions" :key="action.code" :model-value="has(action.code)" :disabled="!has(group.pageCode)" @change="toggle(action.code,$event)">{{action.name}}</el-checkbox></div><div v-else class="no-actions">该页面暂无独立按钮权限</div></section></div></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存配置</el-button></template></el-dialog></div></template>
<script setup>
import{ref,reactive,onMounted}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import PageHeader from '@/components/PageHeader.vue';import api from '@/api/roles';
const rows=ref([]),catalog=ref([]),loading=ref(false),visible=ref(false),saving=ref(false),editing=ref(null);const form=reactive({code:'',name:'',description:'',enabled:true,permissions:[]});const has=code=>form.permissions.includes(code);
function toggle(code,on){const set=new Set(form.permissions);on?set.add(code):set.delete(code);form.permissions=[...set]}function togglePage(group,on){toggle(group.pageCode,on);if(!on)group.actions.forEach(x=>toggle(x.code,false))}function pageCount(row){return(row.permissions||[]).filter(x=>x.startsWith('page:')).length}
async function load(){loading.value=true;try{[rows.value,catalog.value]=await Promise.all([api.list(),api.permissions()])}finally{loading.value=false}}function open(row){editing.value=row||null;Object.assign(form,row?{code:row.code,name:row.name,description:row.description||'',enabled:row.enabled,permissions:[...(row.permissions||[])]}:{code:'',name:'',description:'',enabled:true,permissions:[]});visible.value=true}
async function save(){if(!form.code.trim()||!form.name.trim())return ElMessage.warning('请填写角色编码和名称');saving.value=true;try{const data={...form,code:form.code.trim(),name:form.name.trim()};editing.value?await api.update(editing.value.id,data):await api.create(data);ElMessage.success('角色配置已保存');visible.value=false;await load()}finally{saving.value=false}}async function remove(row){try{await ElMessageBox.confirm(`确定删除角色“${row.name}”吗？`,'删除角色',{type:'warning'})}catch{return}await api.remove(row.id);ElMessage.success('角色已删除');load()}onMounted(load)
</script>
<style scoped>.permission-tip{margin-bottom:12px;padding:10px 12px;background:#f0f9ff;color:#0369a1;border-radius:8px;font-size:13px}.permission-groups{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;max-height:48vh;overflow:auto;padding:2px}.permission-group{border:1px solid #e5eaf1;border-radius:10px;background:#fafbfc;transition:.2s}.permission-group.enabled{border-color:#93c5fd;background:#f8fbff;box-shadow:0 3px 12px rgba(22,119,255,.06)}.permission-group header{display:flex;justify-content:space-between;align-items:center;padding:13px 14px}.permission-group header div{display:flex;flex-direction:column;gap:3px}.permission-group header small{font-size:10px;color:#94a3b8;font-weight:400}.action-area{padding:10px 14px 13px;border-top:1px dashed #dbe5ef;display:flex;flex-wrap:wrap;gap:8px 18px}.action-label{width:100%;font-size:11px;color:#94a3b8}.action-area .el-checkbox{margin:0}.no-actions{padding:10px 14px 13px;border-top:1px dashed #e5eaf1;color:#b0bac7;font-size:12px}@media(max-width:767px){.permission-groups{grid-template-columns:1fr}}</style>
